import pytest
from summarize import summarize


def test_empty_list():
    """Test with empty input."""
    assert summarize([]) == {}


def test_basic_summarization():
    """Test basic summarization of revenue by region."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 150},
    ]
    result = summarize(rows)
    assert result == {'North': 250.0, 'South': 200.0}


def test_numeric_string_revenue():
    """Test that revenue can be numeric strings."""
    rows = [
        {'region': 'East', 'revenue': '100'},
        {'region': 'West', 'revenue': '250.5'},
    ]
    result = summarize(rows)
    assert result == {'East': 100.0, 'West': 250.5}


def test_missing_revenue():
    """Test that rows with missing revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South'},  # missing revenue
        {'region': 'East', 'revenue': 200},
    ]
    result = summarize(rows)
    assert result == {'North': 100.0, 'East': 200.0}


def test_unparseable_revenue():
    """Test that rows with unparseable revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 'invalid'},
        {'region': 'East', 'revenue': None},
        {'region': 'West', 'revenue': '50.25'},
    ]
    result = summarize(rows)
    assert result == {'North': 100.0, 'West': 50.25}


def test_mixed_revenue_types():
    """Test with mixed revenue types (int, float, string)."""
    rows = [
        {'region': 'A', 'revenue': 100},      # int
        {'region': 'B', 'revenue': 200.5},   # float
        {'region': 'C', 'revenue': '300'},   # string
        {'region': 'A', 'revenue': '50.25'}, # string, same region as first
    ]
    result = summarize(rows)
    assert result == {'A': 150.25, 'B': 200.5, 'C': 300.0}


def test_negative_revenue():
    """Test with negative revenue values."""
    rows = [
        {'region': 'North', 'revenue': -50},
        {'region': 'South', 'revenue': 100},
        {'region': 'North', 'revenue': -25},
    ]
    result = summarize(rows)
    assert result == {'North': -75.0, 'South': 100.0}


def test_zero_revenue():
    """Test with zero revenue values."""
    rows = [
        {'region': 'East', 'revenue': 0},
        {'region': 'West', 'revenue': '0'},
        {'region': 'North', 'revenue': 100},
    ]
    result = summarize(rows)
    assert result == {'East': 0.0, 'West': 0.0, 'North': 100.0}


def test_result_is_float():
    """Test that all revenue values in result are floats."""
    rows = [
        {'region': 'A', 'revenue': 100},
        {'region': 'B', 'revenue': '200'},
    ]
    result = summarize(rows)
    assert isinstance(result['A'], float)
    assert isinstance(result['B'], float)


def test_missing_region():
    """Test handling of missing region key."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 200},  # missing region
        {'region': 'East', 'revenue': 300},
    ]
    result = summarize(rows)
    # None can be a key in dict, though unusual
    assert result == {'North': 100.0, None: 200.0, 'East': 300.0}


if __name__ == '__main__':
    pytest.main([__file__, '-v'])

